<?php require 'config/functions.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare('SELECT * FROM products WHERE id=?');$stmt->execute([$id?:0]);$product=$stmt->fetch();if(!$product){http_response_code(404);exit('Produk tidak ditemukan.');}$pageTitle=$product['name'];include 'partials/header.php';?><section class="container section detail"><div class="detail-photo"><img src="<?=e($product['image'])?>" alt="<?=e($product['name'])?>"></div><div><a class="muted" href="products.php">← Kembali ke katalog</a><p class="eyebrow"><?=e($product['category'])?></p><h1 class="page-title"><?=e($product['name'])?></h1><h2><?=rupiah($product['price'])?></h2><p><?=e($product['description'])?></p><p class="muted">Stok tersedia: <?=(int)$product['stock']?></p><form class="detail-form" method="post" action="cart_action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=(int)$product['id']?>"><label>Jumlah <input type="number" name="quantity" value="1" min="1" max="<?=(int)$product['stock']?>" required></label><button class="btn btn-dark" <?=((int)$product['stock']<1?'disabled':'')?>>Tambah ke Keranjang</button></form></div></section><?php include 'partials/footer.php';?>